/* Streaming spectral gate.
 *
 * Each call filters one nfft-sample real frame with a symmetric Hann window,
 * computes the one-sided real spectrum (nfft/2+1 natural complex bins), forms
 * a magnitude profile, estimates the local noise floor from the ntrain bins to
 * the left of each bin, and flags bins above alpha * noise.
 *
 * Bin k of `out_mag` is |X[k]| for k = 0 .. nfft/2.  The transform is
 * unscaled: a unit DC frame has magnitude 1 at bin 0, not nfft.
 */
#ifndef SPECTRAL_GATE_H
#define SPECTRAL_GATE_H

#ifdef __cplusplus
extern "C" {
#endif

typedef struct sg_state sg_state;

typedef struct {
    int nfft;      /* even power of two, >= 8 */
    int ntrain;    /* causal noise-window length, >= 1 */
    float alpha;   /* detection multiplier, > 0 */
} sg_config;

typedef struct {
    float peak;
    int peak_bin;
    int detections;
    float noise_floor;
} sg_report;

sg_state *sg_create(const sg_config *cfg);
void sg_destroy(sg_state *st);

/* Returns 0 on success, -1 on bad arguments.  out_mag has nfft/2+1 floats;
 * flags has nfft/2+1 bytes. */
int sg_process(sg_state *st, const float *input, int n,
               float *out_mag, unsigned char *flags, sg_report *rep);

#ifdef __cplusplus
}
#endif

#endif /* SPECTRAL_GATE_H */

/* Real-FFT plan (VSIPL backend). */
#include "spectral_gate_internal.h"

#include <vsip.h>

#include <stdlib.h>
#include <string.h>

int sg_plan_build(sg_plan *p, int nfft)
{
    if (!p || nfft < 8 || (nfft & (nfft - 1)) != 0) return -1;
    memset(p, 0, sizeof(*p));
    p->nfft = nfft;
    p->nbin = nfft / 2 + 1;
    p->plan = vsip_rcfftop_create_f((vsip_length)nfft, 1.0f, 0,
                                    VSIP_ALG_SPACE);
    p->frame = (float *)calloc((size_t)nfft, sizeof(float));
    p->bin_re = (float *)calloc((size_t)p->nbin, sizeof(float));
    p->bin_im = (float *)calloc((size_t)p->nbin, sizeof(float));
    p->scratch = vsip_cvcreate_f((vsip_length)p->nbin, VSIP_MEM_NONE);
    if (!p->plan || !p->frame || !p->bin_re || !p->bin_im || !p->scratch) {
        sg_plan_destroy(p);
        return -1;
    }
    return 0;
}

void sg_plan_destroy(sg_plan *p)
{
    if (!p) return;
    if (p->plan) vsip_fft_destroy_f((vsip_fft_f *)p->plan);
    if (p->scratch) vsip_cvalldestroy_f((vsip_cvview_f *)p->scratch);
    free(p->frame);
    free(p->bin_re);
    free(p->bin_im);
    memset(p, 0, sizeof(*p));
}

int sg_plan_forward(sg_plan *p, const float *input)
{
    vsip_vview_f *real;
    vsip_cvview_f *spec;
    int i;

    if (!p || !input || !p->plan) return -1;
    real = vsip_vcreate_f((vsip_length)p->nfft, VSIP_MEM_NONE);
    spec = (vsip_cvview_f *)p->scratch;
    if (!real) return -1;

    for (i = 0; i < p->nfft; ++i)
        vsip_vput_f(real, (vsip_index)i, input[i]);
    vsip_rcfftop_f((vsip_fft_f *)p->plan, real, spec);
    for (i = 0; i < p->nbin; ++i) {
        vsip_cscalar_f z = vsip_cvget_f(spec, (vsip_index)i);
        p->bin_re[i] = z.r;
        p->bin_im[i] = z.i;
    }
    vsip_valldestroy_f(real);
    return 0;
}===
/* Frame windowing, magnitude profile and causal noise gate (VSIPL backend). */
#include "spectral_gate_internal.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

sg_state *sg_create(const sg_config *cfg)
{
    sg_state *st;

    if (!cfg || cfg->nfft < 8 || (cfg->nfft & (cfg->nfft - 1)) != 0)
        return NULL;
    if (cfg->ntrain < 1 || !(cfg->alpha > 0.0f)) return NULL;

    st = (sg_state *)calloc(1, sizeof(*st));
    if (!st) return NULL;
    st->ntrain = cfg->ntrain;
    st->alpha = cfg->alpha;
    st->window = (float *)calloc((size_t)cfg->nfft, sizeof(float));
    if (!st->window || sg_plan_build(&st->plan, cfg->nfft) != 0) {
        sg_destroy(st);
        return NULL;
    }
    sg_fill_window(st->window, cfg->nfft);
    return st;
}

void sg_destroy(sg_state *st)
{
    if (!st) return;
    sg_plan_destroy(&st->plan);
    free(st->window);
    free(st);
}

int sg_process(sg_state *st, const float *input, int n,
               float *out_mag, unsigned char *flags, sg_report *rep)
{
    int k, nbin;
    float noise_sum = 0.0f;

    if (!st || !input || !out_mag || !flags) return -1;
    if (n != st->plan.nfft) return -1;
    nbin = st->plan.nbin;

    for (k = 0; k < n; ++k) st->plan.frame[k] = input[k] * st->window[k];
    if (sg_plan_forward(&st->plan, st->plan.frame) != 0) return -1;

    for (k = 0; k < nbin; ++k) {
        const float re = st->plan.bin_re[k], im = st->plan.bin_im[k];
        out_mag[k] = sqrtf(re * re + im * im);
    }

    for (k = 0; k < nbin; ++k) {
        int lo = k - st->ntrain;
        int cnt, j;
        if (lo < 0) lo = 0;
        cnt = k - lo;
        noise_sum = 0.0f;
        for (j = lo; j < k; ++j) noise_sum += out_mag[j];
        if (cnt > 0 && noise_sum > 0.0f) {
            const float noise = noise_sum / (float)cnt;
            flags[k] = (out_mag[k] > st->alpha * noise) ? 1 : 0;
        } else {
            flags[k] = 0;
        }
    }

    if (rep) sg_fill_report(out_mag, flags, nbin, rep);
    return 0;
